package br.com.erp.inventory;

import br.com.erp.auth.*;
import br.com.erp.shared.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LotService {
 private final JdbcTemplate db;private final BranchAccess access;private final WorkflowSupport flow;private final Audit audit;
 public LotService(JdbcTemplate db,BranchAccess access,WorkflowSupport flow,Audit audit){this.db=db;this.access=access;this.flow=flow;this.audit=audit;}
 private record Bucket(UUID id,BigDecimal quantity){}
 private UUID unassigned(Actor a,UUID product){var ids=db.query("SELECT id FROM stock_lot WHERE tenant_id=? AND product_id=? AND code='@UNASSIGNED'",(r,i)->r.getObject(1,UUID.class),a.tenantId(),product);if(!ids.isEmpty())return ids.getFirst();UUID id=UUID.randomUUID();db.update("INSERT INTO stock_lot(id,tenant_id,product_id,code) VALUES(?,?,?,'@UNASSIGNED')",id,a.tenantId(),product);return id;}
 private void add(Actor a,UUID lot,UUID warehouse,BigDecimal delta,UUID operation,UUID movement,UUID source,String kind){var quantities=db.query("SELECT quantity FROM stock_lot_balance WHERE tenant_id=? AND lot_id=? AND warehouse_id=? FOR UPDATE",(r,i)->r.getBigDecimal(1),a.tenantId(),lot,warehouse);BigDecimal before=quantities.isEmpty()?BigDecimal.ZERO:quantities.getFirst(),next=before.add(delta);if(next.signum()<0)throw flow.conflict("Saldo do lote insuficiente.");if(quantities.isEmpty())db.update("INSERT INTO stock_lot_balance(tenant_id,lot_id,warehouse_id,quantity) VALUES(?,?,?,?)",a.tenantId(),lot,warehouse,next);else db.update("UPDATE stock_lot_balance SET quantity=? WHERE tenant_id=? AND lot_id=? AND warehouse_id=?",next,a.tenantId(),lot,warehouse);db.update("INSERT INTO stock_lot_movement(id,tenant_id,lot_id,warehouse_id,operation_id,stock_movement_id,source_operation_id,quantity,kind,actor_id) VALUES(?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),a.tenantId(),lot,warehouse,operation,movement,source,delta,kind,a.userId());}
 @Transactional public void apply(Actor a,UUID operation,UUID movement,UUID warehouse,UUID product,BigDecimal delta,String kind,UUID source){
  // StockService holds the product lock, serializing all bucket changes for this product.
  if(delta.signum()>0){BigDecimal remaining=delta;
   if(kind.equals("TRANSFER_IN")||source!=null){
    UUID original=source==null?operation:source;
    var allocations=db.query("SELECT m.lot_id,-SUM(m.quantity) FROM stock_lot_movement m JOIN stock_lot l ON l.tenant_id=m.tenant_id AND l.id=m.lot_id WHERE m.tenant_id=? AND m.operation_id=? AND l.product_id=? AND m.quantity<0 AND m.stock_movement_id IS NOT NULL GROUP BY m.lot_id ORDER BY m.lot_id",(r,i)->new Bucket(r.getObject(1,UUID.class),r.getBigDecimal(2)),a.tenantId(),original,product);
    for(var bucket:allocations){BigDecimal available=bucket.quantity();if(source!=null)available=available.subtract(db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM stock_lot_movement WHERE tenant_id=? AND source_operation_id=? AND lot_id=? AND quantity>0",BigDecimal.class,a.tenantId(),source,bucket.id()));BigDecimal take=remaining.min(available.max(BigDecimal.ZERO));if(take.signum()>0){add(a,bucket.id(),warehouse,take,operation,movement,source,kind);remaining=remaining.subtract(take);}if(remaining.signum()==0)break;}
    if(!allocations.isEmpty()&&remaining.signum()>0)throw flow.conflict("Retorno excede a alocação original dos lotes.");
   }
   if(remaining.signum()>0)add(a,unassigned(a,product),warehouse,remaining,operation,movement,source,kind);
  }else{
   boolean usable=kind.equals("CONSUMPTION")||kind.equals("INTERNAL_CONSUMPTION");var args=new ArrayList<Object>(List.of(a.tenantId(),warehouse,product));String expiry="";if(usable){expiry=" AND (l.expires_on IS NULL OR l.expires_on>=?)";args.add(LocalDate.now(ZoneId.of("America/Sao_Paulo")));}
   var buckets=db.query("SELECT l.id,b.quantity FROM stock_lot_balance b JOIN stock_lot l ON l.tenant_id=b.tenant_id AND l.id=b.lot_id WHERE b.tenant_id=? AND b.warehouse_id=? AND l.product_id=? AND b.quantity>0"+expiry+" ORDER BY CASE WHEN l.expires_on IS NULL THEN 1 ELSE 0 END,l.expires_on,l.id",(r,i)->new Bucket(r.getObject(1,UUID.class),r.getBigDecimal(2)),args.toArray());BigDecimal remaining=delta.negate();for(var bucket:buckets){BigDecimal take=remaining.min(bucket.quantity());add(a,bucket.id(),warehouse,take.negate(),operation,movement,null,kind);remaining=remaining.subtract(take);if(remaining.signum()==0)break;}if(remaining.signum()>0)throw flow.conflict("Saldo de lotes elegíveis insuficiente. Confira validade e classificação.");
  }
 }
 @Transactional public UUID classify(Actor a,LotController.Classify input){flow.lock(a);if(input.expiresOn()!=null&&(input.expiresOn().getYear()<1||input.expiresOn().getYear()>9999))throw flow.bad("Validade fora do intervalo permitido.");access.requireWarehouse(a,input.warehouseId());var products=db.query("SELECT id FROM product WHERE tenant_id=? AND id=? FOR UPDATE",(r,i)->r.getObject(1,UUID.class),a.tenantId(),input.productId());if(products.isEmpty())throw flow.missing("Produto não encontrado.");if(input.code().startsWith("@"))throw flow.bad("Código reservado.");String hash=flow.hash("LOT_CLASSIFY",input.warehouseId(),input.productId(),input.code(),input.expiresOn(),input.quantity());UUID replay=flow.replay(a,input.requestId(),"LOT_CLASSIFY",hash);if(replay!=null)return replay;
  var lots=db.query("SELECT id,expires_on FROM stock_lot WHERE tenant_id=? AND product_id=? AND code=?",(r,i)->new AbstractMap.SimpleEntry<>(r.getObject(1,UUID.class),r.getObject(2,LocalDate.class)),a.tenantId(),input.productId(),input.code());UUID lot;
  if(lots.isEmpty()){lot=UUID.randomUUID();db.update("INSERT INTO stock_lot(id,tenant_id,product_id,code,expires_on) VALUES(?,?,?,?,?)",lot,a.tenantId(),input.productId(),input.code(),input.expiresOn());}else{lot=lots.getFirst().getKey();if(!Objects.equals(lots.getFirst().getValue(),input.expiresOn()))throw flow.conflict("Lote já cadastrado com outra validade.");}
  add(a,unassigned(a,input.productId()),input.warehouseId(),input.quantity().negate(),input.requestId(),null,null,"CLASSIFY_OUT");add(a,lot,input.warehouseId(),input.quantity(),input.requestId(),null,null,"CLASSIFY_IN");flow.record(a,input.requestId(),"LOT_CLASSIFY",hash,lot);audit.record(a,"STOCK_LOT_CLASSIFIED",lot);return lot;
 }
 @Transactional(readOnly=true) public Map<String,Object> list(Actor a,UUID warehouse,UUID product,boolean expired,int page,int size){access.requireWarehouse(a,warehouse);String where=" WHERE b.tenant_id=? AND b.warehouse_id=?";var args=new ArrayList<Object>(List.of(a.tenantId(),warehouse));if(product!=null){where+=" AND l.product_id=?";args.add(product);}if(expired){where+=" AND l.expires_on<?";args.add(LocalDate.now(ZoneId.of("America/Sao_Paulo")));}long total=db.queryForObject("SELECT COUNT(*) FROM stock_lot_balance b JOIN stock_lot l ON l.tenant_id=b.tenant_id AND l.id=b.lot_id"+where,Long.class,args.toArray());args.add(size);args.add((long)page*size);var items=db.query("SELECT l.id,l.product_id,p.sku,p.name,l.code,l.expires_on,b.quantity FROM stock_lot_balance b JOIN stock_lot l ON l.tenant_id=b.tenant_id AND l.id=b.lot_id JOIN product p ON p.tenant_id=l.tenant_id AND p.id=l.product_id"+where+" ORDER BY l.expires_on,l.code,l.id LIMIT ? OFFSET ?",(r,i)->new LotController.Lot(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),r.getString(5),r.getObject(6,LocalDate.class),r.getBigDecimal(7).toPlainString()),args.toArray());return Map.of("items",items,"total",total,"page",page,"size",size);}
 @Transactional(readOnly=true) public Map<String,Object> movements(Actor a,UUID warehouse,int page,int size){access.requireWarehouse(a,warehouse);var items=db.query("SELECT m.operation_id,m.stock_movement_id,l.code,m.quantity,m.kind,m.created_at,p.sku FROM stock_lot_movement m JOIN stock_lot l ON l.tenant_id=m.tenant_id AND l.id=m.lot_id JOIN product p ON p.tenant_id=l.tenant_id AND p.id=l.product_id WHERE m.tenant_id=? AND m.warehouse_id=? ORDER BY m.created_at DESC,m.id LIMIT ? OFFSET ?",(r,i)->Map.of("operationId",r.getObject(1,UUID.class),"movementId",Objects.toString(r.getObject(2),""),"lot",r.getString(3),"quantity",r.getBigDecimal(4).toPlainString(),"kind",r.getString(5),"createdAt",r.getString(6),"sku",r.getString(7)),a.tenantId(),warehouse,size,(long)page*size);return Map.of("items",items,"total",db.queryForObject("SELECT COUNT(*) FROM stock_lot_movement WHERE tenant_id=? AND warehouse_id=?",Long.class,a.tenantId(),warehouse),"page",page,"size",size);}
}
